//! TypeScript bindings for every type that crosses the Tauri seam, generated by ts-rs into
//! `src/backend/bindings/`. The test fails when the committed files are stale; regenerate with
//! `UPDATE_BINDINGS=1 cargo test bindings`.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use ts_rs::{Config, TS};

fn committed_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../src/backend/bindings")
}

fn export(dir: &Path) {
    // serde writes u64 as a JSON number, not a BigInt.
    let cfg = Config::new().with_large_int("number").with_out_dir(dir);
    let all: [fn(&Config) -> Result<(), ts_rs::ExportError>; 14] = [
        zoo_core::Task::export_all,
        zoo_core::Event::export_all,
        zoo_core::StartMode::export_all,
        zoo_core::CoreError::export_all,
        zoo_core::proxy_pool::ProxyInfo::export_all,
        zoo_core::proxy_pool::ImportResult::export_all,
        crate::commands::error::CommandError::export_all,
        crate::commands::downloads::BatchResult::export_all,
        crate::models::settings::AppSettings::export_all,
        crate::models::settings::Theme::export_all,
        crate::models::settings::SpeedLimitMode::export_all,
        zoo_core::TaskState::export_all,
        zoo_core::SegmentMap::export_all,
        zoo_core::TaskUpdate::export_all,
    ];
    for f in all {
        f(&cfg).expect("export bindings");
    }
}

/// File name -> content, with line endings normalized (git may check files out with CRLF).
fn read_dir(dir: &Path) -> BTreeMap<String, String> {
    std::fs::read_dir(dir)
        .map(|entries| {
            entries
                .map(|e| e.unwrap().path())
                .filter(|p| p.extension().is_some_and(|x| x == "ts"))
                .map(|p| {
                    let name = p.file_name().unwrap().to_string_lossy().into_owned();
                    (name, std::fs::read_to_string(&p).unwrap().replace("\r\n", "\n"))
                })
                .collect()
        })
        .unwrap_or_default()
}

#[test]
fn bindings_are_up_to_date() {
    let committed = committed_dir();
    if std::env::var_os("UPDATE_BINDINGS").is_some() {
        for name in read_dir(&committed).keys() {
            std::fs::remove_file(committed.join(name)).unwrap();
        }
        export(&committed);
        return;
    }

    let fresh = tempfile::tempdir().unwrap();
    export(fresh.path());
    let (expected, actual) = (read_dir(fresh.path()), read_dir(&committed));
    let stale: Vec<_> = expected
        .keys()
        .chain(actual.keys())
        .filter(|name| expected.get(*name) != actual.get(*name))
        .collect();
    assert!(
        stale.is_empty(),
        "src/backend/bindings is out of date for {stale:?}; run `UPDATE_BINDINGS=1 cargo test bindings`"
    );
}
